/// Whether a variation can run for this agent. unsupported always states why and runs nothing; it is never replaced by a weaker simulation.
#[derive(Debug, Clone, PartialEq)]
pub enum PerturbationSupport {
    Supported,
    Unsupported { reason: String },
}

impl PerturbationSupport {
    pub fn kind(&self) -> &'static str {
        match self {
            PerturbationSupport::Supported => "supported",
            PerturbationSupport::Unsupported { .. } => "unsupported",
        }
    }
}

impl Canon for PerturbationSupport {
    fn to_json(&self) -> Json {
        let mut m = BTreeMap::new();
        m.insert("kind".to_owned(), Json::Str(self.kind().to_owned()));
        match self {
            PerturbationSupport::Supported => {}
            PerturbationSupport::Unsupported { reason } => {
                put(&mut m, "reason", reason);
            }
        }
        Json::Obj(m)
    }
    fn from_json(j: &Json, path: &str) -> Result<Self, DecodeError> {
        let m = obj(j, path)?;
        let kind: String = req(m, "kind", path)?;
        match kind.as_str() {
            "supported" => {
                only_fields(m, &["kind"], path)?;
                Ok(PerturbationSupport::Supported)
            }
            "unsupported" => {
                only_fields(m, &["reason", "kind"], path)?;
                Ok(PerturbationSupport::Unsupported { reason: req(m, "reason", path)? })
            }
            other => Err(unknown_variant(path, "PerturbationSupport", other)),
        }
    }
}

